SELECT (xsd:decimal(?paidCount) / ?totalCount * 100 AS ?percentage_not_free)

FROM <https://omnix.dev/graphs/demo-tenant/kg/events-sf>
WHERE {
    {
        SELECT (COUNT(DISTINCT ?event) AS ?totalCount)
        WHERE {
            ?event a <https://omnix.dev/types/Event> .
            ?event <https://omnix.dev/onto/event_category> ?category .
            ?category <https://omnix.dev/types/EventCategory/attrs/name> "Business & Entrepreneurship" .
        }
    }
    {
        SELECT (COUNT(DISTINCT ?event) AS ?paidCount)
        WHERE {
            ?event a <https://omnix.dev/types/Event> .
            ?event <https://omnix.dev/onto/event_category> ?category .
            ?category <https://omnix.dev/types/EventCategory/attrs/name> "Business & Entrepreneurship" .
            ?event <https://omnix.dev/types/Event/attrs/is_free> false .
        }
    }
}

SELECT ?submissionMethodName (SUM(IF(?consumerConsentProvided = "Consent provided", 1, 0)) AS ?consentedComplaints) (COUNT(?complaint) AS ?totalComplaints) ((SUM(IF(?consumerConsentProvided = "Consent provided", 1, 0)) / COUNT(?complaint)) AS ?consentRate)

FROM <https://omnix.dev/graphs/demo-tenant/kg/cfpb-complaints>
WHERE {
  ?complaint <http://www.w3.org/1999/02/22-rdf-syntax-ns#type> <https://omnix.dev/types/ConsumerComplaint> .
  ?complaint <https://omnix.dev/onto/submitted_via> ?submissionMethod .
  ?submissionMethod <https://omnix.dev/types/SubmissionMethod/attrs/name> ?submissionMethodName .
  OPTIONAL { ?complaint <https://omnix.dev/types/ConsumerComplaint/attrs/consumer_consent_provided> ?consumerConsentProvided . }
}
GROUP BY ?submissionMethodName
ORDER BY DESC(?consentRate)

SELECT (AVG(?orbital_period) AS ?average_orbital_period)

FROM <https://omnix.dev/graphs/demo-tenant/kg/exoplanets>
WHERE {
  ?exoplanet <http://www.w3.org/1999/02/22-rdf-syntax-ns#type> <https://omnix.dev/types/Exoplanet> .
  ?exoplanet <https://omnix.dev/onto/discovery_facility> ?facility .
  ?exoplanet <https://omnix.dev/types/Exoplanet/attrs/orbital_period> ?orbital_period .
  {
    SELECT ?facility
    WHERE {
      ?exo <http://www.w3.org/1999/02/22-rdf-syntax-ns#type> <https://omnix.dev/types/Exoplanet> .
      ?exo <https://omnix.dev/onto/discovery_facility> ?facility .
    }
    GROUP BY ?facility
    HAVING (COUNT(?exo) > 50)
  }
}

SELECT (SUM(?bedrooms) AS ?totalBedrooms)  FROM <https://omnix.dev/graphs/demo-tenant/kg/zillow-austin>
WHERE {
  {
    SELECT ?broker ?brokerName (COUNT(?listing) AS ?listingCount) WHERE {
      ?listing <http://www.w3.org/1999/02/22-rdf-syntax-ns#type> <https://omnix.dev/types/PropertyListing> .
      ?listing <https://omnix.dev/onto/broker> ?broker .
      ?broker <https://omnix.dev/types/Broker/attrs/name> ?brokerName .
    }
    GROUP BY ?broker ?brokerName
    ORDER BY DESC(?listingCount)
    LIMIT 3
  }
  ?listing <https://omnix.dev/onto/broker> ?broker .
  ?listing <https://omnix.dev/types/PropertyListing/attrs/bedrooms> ?bedrooms .
}
